{
  "contract": "Dao",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "deposit",
      "withdraw"
    ],
    "justification": "Both deposit and withdraw functions interact with the balances storage variable, which is exposed during the callback in withdraw."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "deposit"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "end"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "_sum_balances",
      "sol_type": "uint",
      "meaning": "Sum of all balances in the contract",
      "backed_by_storage": true
    },
    {
      "name": "_ethBal",
      "sol_type": "uint",
      "meaning": "Total ether balance of the contract",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_balances == _ethBal + inFlight",
    "stable_formula": "_sum_balances == _ethBal",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_balances == _ethBal",
    "rule": "mapping-conservation"
  }
}
